import z3

def solve():
    # 14 vertices
    n = 14

    # Create boolean variables for each possible edge
    edges = {}
    for i in range(n):
        for j in range(i + 1, n):
            edges[(i, j)] = z3.Bool(f"e_{i}_{j}")

    solver = z3.Solver()

    # Add partial assignments
    fixed_edges = [(4,5), (0,10), (2,7), (6,8), (2,8), (1,6), (0,9), (5,8)]
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) in fixed_edges or (j, i) in fixed_edges:
                solver.add(edges[(min(i, j), max(i, j))] == True)

    # Add degree constraints
    for i in range(n):
        incident_edges = []
        for j in range(n):
            if i < j:
                incident_edges.append(edges[(i, j)])
            elif i > j:
                incident_edges.append(edges[(j, i)])

        # Sum of booleans
        deg = z3.Sum([z3.If(e, 1, 0) for e in incident_edges])
        solver.add(deg >= 3)
        solver.add(deg <= 6)

    if solver.check() == z3.sat:
        m = solver.model()
        result = []
        for i in range(n):
            for j in range(i + 1, n):
                if z3.is_true(m[edges[(i, j)]]):
                    result.append((i, j))
        print("SAT")
        print(result)
    else:
        print("UNSAT")

solve()

