from pysat.formula import IDPool

def solve():
    n = 14

    vpool = IDPool()

    # Map edges to variables
    edge_vars = {}
    for i in range(n):
        for j in range(i + 1, n):
            edge_vars[(i, j)] = vpool.id(f"e_{i}_{j}")

    solver = Glucose3()

    # Add partial assignments
    fixed_edges = [(4,5), (0,10), (2,7), (6,8), (2,8), (1,6), (0,9), (5,8)]
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) in fixed_edges or (j, i) in fixed_edges:
                solver.add_clause([edge_vars[(min(i, j), max(i, j))]])

    # Add degree constraints
    for i in range(n):
        incident_vars = []
        for j in range(n):
            if i < j:
                incident_vars.append(edge_vars[(i, j)])
            elif i > j:
                incident_vars.append(edge_vars[(j, i)])

        # deg >= 3
        cnf_ge = CardEnc.atleast(lits=incident_vars, bound=3, encoding=EncType.seqcounter, vpool=vpool)
        for clause in cnf_ge.clauses:
            solver.add_clause(clause)

        # deg <= 6
        cnf_le = CardEnc.atmost(lits=incident_vars, bound=6, encoding=EncType.seqcounter, vpool=vpool)
        for clause in cnf_le.clauses:
            solver.add_clause(clause)

    if solver.solve():
        model = solver.get_model()
        model_set = set(model)
        result = []
        for i in range(n):
            for j in range(i + 1, n):
                if edge_vars[(i, j)] in model_set:
                    result.append([i, j])
        print("SAT")
        print(result)
    else:
        print("UNSAT")

solve()
